export default {async fetch(request){const u=new URL(request.url);if(u.pathname==="/manifest.webmanifest")return new Response("{\"id\":\"/\",\"name\":\"AppleRAVEN — Connect\",\"short_name\":\"AppleRAVEN\",\"description\":\"AppleRAVEN onboarding and browser-local ELYSIUM demonstration\",\"start_url\":\"/\",\"scope\":\"/\",\"display\":\"standalone\",\"background_color\":\"#0b0f16\",\"theme_color\":\"#0b0f16\",\"icons\":[{\"src\":\"/icon.svg\",\"sizes\":\"any\",\"type\":\"image/svg+xml\",\"purpose\":\"any maskable\"}]}",{headers:{"content-type":"application/manifest+json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff"}});if(u.pathname==="/icon.svg")return new Response("<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\"><rect width=\"512\" height=\"512\" rx=\"100\" fill=\"#0b0f16\"/><path d=\"M88 386L256 105 424 386\" stroke=\"#91bbe8\" stroke-width=\"42\" stroke-linecap=\"round\" stroke-linejoin=\"round\" fill=\"none\"/><path d=\"M174 309H338\" stroke=\"#e4ecf6\" stroke-width=\"32\" stroke-linecap=\"round\"/><circle cx=\"392\" cy=\"135\" r=\"24\" fill=\"#d9e7f8\"/></svg>",{headers:{"content-type":"image/svg+xml; charset=utf-8","cache-control":"public, max-age=3600","x-content-type-options":"nosniff"}});if(u.pathname==="/health")return new Response(JSON.stringify({service:"AppleRAVEN Onboarding",mode:"public_information_and_browser_local_elysium_demo",mac_paired:false}),{headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store"}});if(u.pathname!=="/"&&u.pathname!=="/demo"&&u.pathname!=="/setup")return new Response("Not found",{status:404});return new Response("<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex,nofollow\"><title>AppleRAVEN | Connect &amp; Demonstrate</title><meta name=\"theme-color\" content=\"#0b0f16\"><meta name=\"apple-mobile-web-app-capable\" content=\"yes\"><meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\"><meta name=\"apple-mobile-web-app-title\" content=\"AppleRAVEN\"><link rel=\"manifest\" href=\"/manifest.webmanifest\">\n<style>\n:root{color-scheme:dark;font-family:system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;background:#0b0f16;color:#edf2fa}\n*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 85% 0%,#182a40 0%,transparent 43%),#0b0f16}\nmain{width:min(1050px,calc(100% - 36px));margin:0 auto;padding:42px 0 75px}\na{color:#b0d4ff;text-underline-offset:3px}nav{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #293545;padding-bottom:26px}\n.logo{font-weight:750;letter-spacing:.15em;font-size:18px}.mark{display:inline-grid;place-items:center;width:38px;height:38px;border:1px solid #6783a9;border-radius:13px;margin-right:10px}\n.eyebrow{color:#87abc9;font-size:12px;letter-spacing:.18em;text-transform:uppercase}h1{font-size:clamp(36px,6vw,66px);letter-spacing:-.05em;line-height:1.08;max-width:820px;margin:45px 0 15px}\nh2{font-size:23px;letter-spacing:-.025em}p{color:#b5c1d0;line-height:1.65}.lead{font-size:18px;max-width:670px}\n.layout{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:32px 0 46px}\n.panel{background:#141e2a;border:1px solid #293646;border-radius:20px;padding:22px;min-width:0}.panel h3{margin:8px 0 4px}\n.number{font-size:12px;color:#93a9c4;letter-spacing:.12em}.tag{font-size:11px;letter-spacing:.07em;padding:5px 10px;border-radius:40px;border:1px solid #49617c;color:#cadcf0}\n.link{display:inline-flex;min-height:42px;align-items:center;justify-content:center;background:#e4ecf6;color:#162333;border-radius:12px;text-decoration:none;padding:10px 15px;font-weight:650;margin-top:12px}\n.link.secondary{background:#26384d;color:#dce9f7}.link:hover{filter:brightness(1.08)}\n.demo{border-top:1px solid #2b3645;padding-top:32px}.row{display:flex;align-items:center;gap:10px;flex-wrap:wrap}\n.tab{border:1px solid #3d4e63;background:transparent;color:#bfcddd;padding:10px 15px;border-radius:10px;cursor:pointer}\n.tab[aria-selected=\"true\"]{background:#dfe9f5;color:#162333;border-color:#dfe9f5;font-weight:700}\n.workspace{display:grid;grid-template-columns:minmax(0,1fr) 240px;gap:18px;margin-top:18px}\ninput{background:#0d1520;color:#f2f5fa;border:1px solid #425168;border-radius:10px;min-height:46px;padding:12px;width:100%;flex:1}\nbutton.action{background:#c9daed;color:#142234;border:0;border-radius:10px;min-height:45px;padding:0 18px;cursor:pointer;font-weight:700}\nul{list-style:none;padding:0;margin:14px 0 0}li{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:12px 0;border-bottom:1px solid #293544}\nsmall{color:#93a6bb}.remove{color:#ffcbcb;background:transparent;border:0;cursor:pointer}\nfooter{color:#9aacc1;font-size:12px;margin-top:44px;line-height:1.8}\n@media(max-width:700px){.layout{grid-template-columns:1fr}.workspace{grid-template-columns:1fr}main{width:min(100% - 26px,1050px)}}\n</style>\n<main><nav><div class=\"logo\"><span class=\"mark\">A</span> APPLE<span style=\"color:#91bade\">RAVEN</span></div><span class=\"tag\">OWNER CONNECTION PILOT</span></nav>\n<div class=\"eyebrow\" style=\"margin-top:40px\">AppleRAVEN · MacBook Air M1</div><h1>Install. Pair. Connect.</h1>\n<p class=\"lead\">A private Apple device connection for your existing ChatGPT account. The native Mac agent is independent of Remote Desktop Commander. The ELYSIUM workspace below is a separate, browser-local demonstration.</p>\n<p class=\"lead\" style=\"font-size:15px\">AppleRAVEN works in Safari on iPhone and iPad and desktop browsers. In Safari choose <strong>Share → Add to Home Screen</strong> for an app-like interface. This browser demonstration does not grant Mac control; private actions require a paired device and authenticated owner.</p><section class=\"layout\" aria-label=\"Connection steps\">\n<div class=\"panel\"><div class=\"number\">01 / INSTALL</div><h3>Get AppleRAVEN for Mac</h3><p>Run the independent AppleRAVEN Mac agent from the existing private project installer and approve pairing with your owner login. No Remote Desktop Commander, public Mac port, or desktop disk image is required.</p><a class=\"link secondary\" target=\"_blank\" rel=\"noopener\" href=\"https://github.com/lucasbuzek/Lucas-Private-edenOS-apps/tree/candidate/appleraven-native-dmg-elysium-proof-20261028/AppleRAVEN/mac\">Mac agent source</a><p><small>Test candidate · Mac execution still unverified</small></p></div>\n<div class=\"panel\"><div class=\"number\">02 / APPROVE</div><h3>Pair your Mac</h3><p>When the standalone Mac agent displays a one-time code, authenticate using your existing Cloudflare Access owner login and approve that code.</p><a class=\"link\" target=\"_blank\" rel=\"noopener\" href=\"https://appleraven-private.lucasravensnest.workers.dev/pair\">Open owner pairing</a><p><small>Owner login required · Never enter OTP in chat</small></p></div>\n<div class=\"panel\"><div class=\"number\">03 / CONNECT</div><h3>Open ChatGPT plugin</h3><p>Continue with the existing private AppleRAVEN plugin. First request the owner and device status, then the native Shortcuts test after pairing.</p><a class=\"link secondary\" target=\"_blank\" rel=\"noopener\" href=\"https://chatgpt.com/plugins/plugins_6ae05fb243a48191a7cd678e20ee608c\">AppleRAVEN in ChatGPT</a><p><small>Real MCP connection depends on client eligibility and owner OAuth</small></p></div>\n</section>\n<section class=\"demo\" aria-label=\"ELYSIUM proof demonstration\"><div class=\"row\" style=\"justify-content:space-between\"><div><div class=\"eyebrow\">SEPARATE PRODUCT DEMONSTRATION</div><h2>ELYSIUM · Workspace preview</h2></div><span class=\"tag\">BROWSER-LOCAL ONLY</span></div>\n<p>Exercise a working example of Personal, Business and Organization task organization. Entries stay in this browser; they are not uploaded to AppleRAVEN or connected to the Mac.</p>\n<div class=\"row\" role=\"tablist\" aria-label=\"Workspace types\"><button class=\"tab\" role=\"tab\" data-space=\"Personal\" aria-selected=\"true\">Personal</button><button class=\"tab\" role=\"tab\" data-space=\"Business\" aria-selected=\"false\">Business</button><button class=\"tab\" role=\"tab\" data-space=\"Organization\" aria-selected=\"false\">Organization</button></div>\n<div class=\"workspace\"><section class=\"panel\"><h3 id=\"heading\">Personal tasks</h3><form id=\"taskform\" class=\"row\"><input id=\"tasktext\" aria-label=\"New task\" maxlength=\"120\" required placeholder=\"Add a demonstration task\"><button class=\"action\">Add</button></form><ul id=\"tasks\"></ul><p id=\"empty\" style=\"font-size:14px\">No tasks yet.</p></section>\n<aside class=\"panel\"><div class=\"number\">DEMO ACTIVITY</div><h3 id=\"count\">0 tasks</h3><p>Try adding and removing a task in each workspace. These are isolated sample browser entries, not your real ELYSIUM or AppleRAVEN accounts.</p><button class=\"tab\" id=\"clear\" type=\"button\">Clear this demo workspace</button></aside></div></section>\n<footer>AppleRAVEN connection pilot · Existing Cloudflare owner service preserved · No login fields or credentials on this public information page · ELYSIUM remains an autonomous application · No live Mac status is asserted here.</footer></main>\n<script>\n(()=>{const spaces=[\"Personal\",\"Business\",\"Organization\"];let active=\"Personal\";const key=s=>\"appleraven_elysium_demo_2026_\"+s;let list=[];\nfunction load(){try{let a=JSON.parse(localStorage.getItem(key(active))||\"[]\");list=Array.isArray(a)?a.filter(x=>typeof x===\"string\").slice(0,50):[]}catch{list=[]}}\nfunction save(){try{localStorage.setItem(key(active),JSON.stringify(list))}catch{}}\nfunction render(){document.getElementById(\"heading\").textContent=active+\" tasks\";document.getElementById(\"count\").textContent=list.length+\" tasks\";const ul=document.getElementById(\"tasks\");ul.replaceChildren();list.forEach((s,i)=>{const li=document.createElement(\"li\"),t=document.createElement(\"span\"),b=document.createElement(\"button\");t.textContent=s;b.textContent=\"Remove\";b.type=\"button\";b.className=\"remove\";b.setAttribute(\"aria-label\",\"Remove task\");b.addEventListener(\"click\",()=>{list.splice(i,1);save();render()});li.append(t,b);ul.append(li)});document.getElementById(\"empty\").hidden=list.length>0;document.querySelectorAll(\"[data-space]\").forEach(b=>b.setAttribute(\"aria-selected\",String(b.dataset.space===active)))}\ndocument.querySelectorAll(\"[data-space]\").forEach(b=>b.addEventListener(\"click\",()=>{active=spaces.includes(b.dataset.space)?b.dataset.space:\"Personal\";load();render()}));\ndocument.getElementById(\"taskform\").addEventListener(\"submit\",e=>{e.preventDefault();const input=document.getElementById(\"tasktext\"),v=input.value.trim();if(v&&list.length<50){list.push(v);save();render();input.value=\"\"}});\ndocument.getElementById(\"clear\").addEventListener(\"click\",()=>{list=[];save();render()});load();render()})();\n</script><script>/* AppleRAVEN onboarding: optional same-origin WebMCP demo tools.\n * Browser localStorage only; no AppleRAVEN OAuth, device access or cloud write.\n * Feature-detect the October 2026 Chrome document.modelContext API.\n */\n(() => {\n  const api = document.modelContext;\n  if (!api || typeof api.registerTool !== 'function') return;\n  const names = ['Personal', 'Business', 'Organization'];\n  const key = s => 'appleraven_elysium_demo_2026_' + s;\n  const read = space => {\n    if (!names.includes(space)) return {error: 'Unsupported workspace'};\n    try {\n      const data = JSON.parse(localStorage.getItem(key(space)) || '[]');\n      const tasks = Array.isArray(data) ? data.filter(x => typeof x === 'string').slice(0, 50) : [];\n      return {workspace: space, tasks, count: tasks.length, storage: 'browser-local-demonstration'};\n    } catch {\n      return {error: 'Local demonstration data unavailable'};\n    }\n  };\n  const controller = new AbortController();\n  const listTool = {\n    name: 'elysium_demo_list_tasks',\n    description: 'Read the sample tasks in one local ELYSIUM demonstration workspace. This is not real ELYSIUM or Mac data.',\n    inputSchema: {type: 'object', properties: {workspace: {type: 'string', enum: names}}, required: ['workspace'], additionalProperties: false},\n    execute: async ({workspace}) => read(workspace),\n    annotations: {readOnlyHint: true, destructiveHint: false, openWorldHint: false}\n  };\n  const addTool = {\n    name: 'elysium_demo_add_task',\n    description: 'Add one task to the browser-local demonstration using the visible task form. No cloud or Apple device changes.',\n    inputSchema: {type: 'object', properties: {\n      workspace: {type: 'string', enum: names},\n      text: {type: 'string', minLength: 1, maxLength: 120}\n    }, required: ['workspace', 'text'], additionalProperties: false},\n    execute: async ({workspace, text}) => {\n      if (!names.includes(workspace) || typeof text !== 'string' || !text.trim() || text.length > 120) {\n        return {error: 'Invalid workspace or task'};\n      }\n      const existing = read(workspace);\n      if (existing.error) return existing;\n      if (existing.count >= 50) return {error: 'Local demonstration task limit reached'};\n      const tab = [...document.querySelectorAll('[data-space]')].find(x => x.dataset.space === workspace);\n      const form = document.getElementById('taskform');\n      const input = document.getElementById('tasktext');\n      if (!tab || !form || !input) return {error: 'Demonstration interface unavailable'};\n      tab.click();\n      input.value = text.trim();\n      form.dispatchEvent(new Event('submit', {bubbles: true, cancelable: true}));\n      return read(workspace);\n    },\n    annotations: {readOnlyHint: false, destructiveHint: false, openWorldHint: false}\n  };\n  Promise.all([\n    api.registerTool(listTool, {signal: controller.signal}),\n    api.registerTool(addTool, {signal: controller.signal})\n  ]).catch(() => { controller.abort(); });\n  window.addEventListener('pagehide', () => controller.abort(), {once: true});\n})();\n</script></html>",{headers:{"content-type":"text/html; charset=utf-8","x-content-type-options":"nosniff","referrer-policy":"no-referrer","content-security-policy":"default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'none'; img-src 'self'; manifest-src 'self'; base-uri 'none'; frame-ancestors 'none'","cache-control":"no-store"}})}}
